#include <vector>

struct NivelInvalido {};
class Nivel {
public:
    Nivel() {}
    Nivel(int inicial) : valor_{inicial} {
        if (valor_ < 0 || valor_ > 3) { throw NivelInvalido{}; }
    }
    int valor() const { return valor_; }
private:
    int valor_ = 0;
};

int main() {
    Nivel primero;
    Nivel segundo{3};
    std::vector<Nivel> niveles(2);
    std::cout << primero.valor() << ":" << segundo.valor() << " ";
    for (const auto& nivel : niveles) { std::cout << nivel.valor(); }
    try {
        Nivel rechazado{4};
        std::cout << rechazado.valor();
    } catch (const NivelInvalido&) { std::cout << " Rechazado"; }
    return 0;
}

